Tool response:
Tool: find_animals_by_tag_and_mob
Description: Find Animals By Tag And Mob
Parameters:
    {
      "type": "object",
      "properties": {
        "tag_prefix": {
          "type": "string",
          "description": "Tag ID prefix to filter animals (e.g., 'AUS')",
          "title": "Tag Prefix"
        },
        "mob_name": {
          "type": "string",
          "description": "Name of the mob to filter animals (e.g., 'Home Paddock')",
          "title": "Mob Name"
        }
      },
      "required": [
        "tag_prefix",
        "mob_name"
      ]
    }
